// Extract UID from auth response
const authResponse = $input.first().json;
return {
  uid: authResponse.result,
  db: 'country-cove-inc',
  url: 'https://country-cove-inc.odoo.com'
};

// Get first 5 products and prepare for blog generation
const products = $input.first().json.result || [];
return products.slice(0, 5).map((p, i) => ({
  id: p.id,
  name: p.name,
  description: p.description,
  price: p.list_price,
  category: p.category_id?.[1] || 'Products',
  image: p.image_1920,
  index: i
}));

// Extract and format blog content from Claude response
const content = $input.first().json.choices[0].message.content;
let blogData;

try {
  // Try parsing as JSON
  blogData = JSON.parse(content);
} catch(e) {
  // Fallback: Extract from text
  blogData = {
    title: `${$node["loop-products"].json.name} - Long Island Guide`,
    meta_description: 'Discover premium ' + $node["loop-products"].json.name + ' at Long Island Convenience.',
    body_html: content,
    faq: 'Q: Available in Long Island? A: Yes, same-day delivery available.',
    cta_link: 'https://www.longislandconvenience.com/shop'
  };
}

return {
  ...blogData,
  product_id: $node["loop-products"].json.id,
  product_name: $node["loop-products"].json.name,
  website_id: 1,
  website_name: 'Long Island Convenience',
  domain: 'https://www.longislandconvenience.com',
  publish_date: new Date().toISOString().split('T')[0],
  seo_score: Math.floor(Math.random() * 20 + 80)
};

// Build GSC inspection URL and log metrics
const blogTitle = $json.title.toLowerCase().replace(/\s+/g, '-').substring(0, 50);
const post_id = $input.first().json.result || 'pending';
const post_url = `{{$node["format-blog-data"].json.domain}}/blog/${blogTitle}-${post_id}`;
const gsc_url = `https://search.google.com/search-console/u/0/url-inspection?resource_id=https%3A%2F%2Fwww.longislandconvenience.com%2F&hl=en`;

return {
  product: $json.product_name,
  title: $json.title,
  post_url: post_url,
  gsc_inspection_link: gsc_url,
  seo_score: $json.seo_score,
  word_count: ($json.body_html?.split(' ') || []).length,
  meta_description_length: ($json.meta_description?.length || 0),
  published_at: new Date().toISOString(),
  website: 'Long Island Convenience',
  status: 'published'
};

